-- Sách Hay | bản nộp Giai đoạn 1 | MySQL 8.0+

-- Chỉ dùng dữ liệu khởi tạo và tài khoản khách giả lập, không xuất dữ liệu vận hành.

CREATE DATABASE IF NOT EXISTS sachhay_gd1 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE sachhay_gd1;

START TRANSACTION;

CREATE TABLE books (
    `id` VARCHAR(80) PRIMARY KEY, `title` VARCHAR(255) NOT NULL, `price` BIGINT NOT NULL CHECK(price >= 0),
    `stock` BIGINT NOT NULL CHECK(stock >= 0), `sold_count` BIGINT NOT NULL DEFAULT 0 CHECK(sold_count >= 0),
    `active` BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), `cover_path` LONGTEXT NOT NULL,
    `cover_base64` LONGTEXT, `catalog` JSON, `created_at` VARCHAR(35),
    INDEX books_catalog (active, created_at)
) ENGINE=InnoDB;































CREATE TABLE customers (
    `id` VARCHAR(80) PRIMARY KEY, `email` VARCHAR(254) NOT NULL UNIQUE, `password_hash` VARCHAR(255) NOT NULL
) ENGINE=InnoDB;


CREATE TABLE vouchers (
    `code` VARCHAR(40) PRIMARY KEY, `kind` VARCHAR(16) NOT NULL CHECK(kind IN ('fixed','percentage','shipping')),
    `value` BIGINT NOT NULL CHECK(value > 0), `minimum` BIGINT NOT NULL CHECK(minimum >= 0), `cap` BIGINT,
    `active` BIGINT NOT NULL DEFAULT 1, `valid_from` BIGINT NOT NULL, `valid_until` BIGINT NOT NULL,
    `used` BIGINT NOT NULL DEFAULT 0, `max_uses` BIGINT DEFAULT 100, `max_per_user` BIGINT NOT NULL DEFAULT 1
) ENGINE=InnoDB;


CREATE TABLE voucher_uses (
    `code` VARCHAR(40) NOT NULL, `customer_id` VARCHAR(80) NOT NULL,
    `used` BIGINT NOT NULL CHECK(used > 0), PRIMARY KEY(code,customer_id),
    FOREIGN KEY (`code`) REFERENCES `vouchers`(`code`),
    FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`)
) ENGINE=InnoDB;

CREATE TABLE orders (
    `id` VARCHAR(80) PRIMARY KEY, `request_key` VARCHAR(80) NOT NULL UNIQUE, `request_hash` CHAR(64) NOT NULL,
    `customer_id` VARCHAR(80), `owner_key` CHAR(64) NOT NULL,
    `order_code` VARCHAR(40) NOT NULL UNIQUE, `payment_method` VARCHAR(20) NOT NULL CHECK(payment_method IN ('COD','STORE_PICKUP','BANK_TRANSFER')),
    `total` BIGINT NOT NULL CHECK(total >= 0), `payload` JSON NOT NULL,
    `bank` JSON, `payment_token_hash` CHAR(64), `payment_status` VARCHAR(20), `paid_at` VARCHAR(35), `created_at` VARCHAR(35) NOT NULL,
    FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`),
    INDEX orders_customer (customer_id, created_at)
) ENGINE=InnoDB;

CREATE TABLE sepay_events (
    `id` VARCHAR(80) PRIMARY KEY, `order_code` VARCHAR(40), `amount` BIGINT NOT NULL, `result` VARCHAR(40) NOT NULL, `transferred_at` VARCHAR(35) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE contacts (
    `id` VARCHAR(80) PRIMARY KEY, `name` VARCHAR(100) NOT NULL, `email` VARCHAR(254) NOT NULL, `message` LONGTEXT NOT NULL, `created_at` VARCHAR(35) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE request_limits (
    `bucket` CHAR(64) PRIMARY KEY, `attempts` BIGINT NOT NULL, `expires_at` BIGINT NOT NULL,
    INDEX request_limits_expiry (expires_at)
) ENGINE=InnoDB;

CREATE TABLE newsletter_subscribers (`email` VARCHAR(254) PRIMARY KEY, `created_at` VARCHAR(35) NOT NULL) ENGINE=InnoDB;

CREATE TABLE schema_ready (`version` BIGINT NOT NULL) ENGINE=InnoDB;


COMMIT;
